"use strict";(Array.isArray(self.webpackChunkwoocommerce_multivendor_marketplace_docs)?self.webpackChunkwoocommerce_multivendor_marketplace_docs:self.webpackChunkwoocommerce_multivendor_marketplace_docs=[]).push([[5232],{85041(e,t,o){o.r(t),o.d(t,{comp:()=>c,data:()=>g});var i=o(20641);const a=o.p+"assets/img/marketplace-admin-product-page-ai-assistant-button.0d3dcf34.webp",r=o.p+"assets/img/marketplace-admin-product-ai-assistant-modal.e093b687.webp",n=o.p+"assets/img/marketplace-admin-editor-magic-ai-toolbar.675a3e07.webp",s=o.p+"assets/img/marketplace-admin-editor-magic-ai-modal.c583b06a.webp",l=o.p+"assets/img/marketplace-admin-category-magic-ai.d6de5a13.webp",d={},c=(0,o(66262).A)(d,[["render",function(e,t){return(0,i.uX)(),(0,i.CE)("div",null,t[0]||(t[0]=[(0,i.Fv)('<h1 id="magic-ai-admin-content-generation" tabindex="-1"><a class="header-anchor" href="#magic-ai-admin-content-generation"><span>Magic AI Admin Content Generation</span></a></h1><p>Store administrators, merchandisers, and catalog managers can generate, polish, and optimize product listings directly within the native WooCommerce catalog workflow on <strong>Add New Product</strong> (<code>Products &gt; Add New</code>), <strong>Edit Product</strong> (<code>Products &gt; Edit</code>), and <strong>Category</strong> (<code>Products &gt; Categories</code>) screens.</p><table><thead><tr><th>1. AI Assistant Modal</th><th>2. Inline WYSIWYG Editor AI</th><th>3. AI Product Image Generator</th></tr></thead><tbody><tr><td>• <strong>&quot;Generate content&quot;</strong> top launch button<br>• Multi-field catalog drafting<br>• Interactive review modal<br>• Selective field application</td><td>• <strong>&quot;Magic AI&quot;</strong> button on editor toolbar<br>• Targeted text drafting and copy refinement<br>• Custom prompts per editor<br>• 1-Click editor insertion</td><td>• <strong>&quot;Generate Image&quot;</strong> button on editor toolbar<br>• Custom AI artwork creation<br>• Multiple aspect ratios (1:1, 2:3, 3:2)<br>• 1-Click set as Product Featured Image</td></tr></tbody></table><hr><h2 id="_1-the-product-page-ai-assistant-multi-field-generator" tabindex="-1"><a class="header-anchor" href="#_1-the-product-page-ai-assistant-multi-field-generator"><span>1. The Product Page AI Assistant (Multi-Field Generator)</span></a></h2><p>The <strong>AI Assistant</strong> is a multi-field content drafting engine built right into the WooCommerce product editor.</p><h3 id="where-to-find-it" tabindex="-1"><a class="header-anchor" href="#where-to-find-it"><span>Where to Find It</span></a></h3><p>On the WooCommerce <strong>Add New Product</strong> or <strong>Edit Product</strong> screen, look near the top right of the page (beside the main product title heading) for the blue <strong>Generate content</strong> button.</p><p><a class="doc-image-link" href="./assets/marketplace-admin-product-page-ai-assistant-button.webp"><img src="'+a+'" alt="Generate Content Button on WooCommerce Product Page"></a></p><h3 id="step-by-step-workflow" tabindex="-1"><a class="header-anchor" href="#step-by-step-workflow"><span>Step-by-Step Workflow</span></a></h3><ol><li><strong>Click &quot;Generate content&quot;:</strong> Opens the interactive assistant modal.</li><li><strong>Describe Your Product:</strong> Enter notes, bullet points, or raw supplier specifications in the prompt box (up to 2,000 characters).</li><li><strong>Select Target Fields:</strong> Check the field pills you want the AI to draft: <ul><li><em>Product Name</em></li><li><em>Short Description</em></li><li><em>Product Description</em></li><li><em>Regular Price</em></li><li><em>Sale Price</em></li></ul></li><li><strong>Generate:</strong> Click the <strong>Generate</strong> button. The engine drafts values across all selected fields in 5 to 15 seconds.</li><li><strong>Review &amp; Refine:</strong><ul><li>Every generated value appears in the review step marked with a <strong>&quot;new&quot;</strong> badge.</li><li>Click the <strong>Regenerate</strong> button beside any individual field to request an alternative variation.</li><li>Uncheck any field you prefer not to use.</li></ul></li><li><strong>Apply to Form:</strong> Click <strong>Apply fields</strong>. The chosen values immediately populate the corresponding live WooCommerce form inputs.</li></ol><p><a class="doc-image-link" href="./assets/marketplace-admin-product-ai-assistant-modal.webp"><img src="'+r+'" alt="Product Page AI Assistant Generation and Review Modal"></a></p><div class="hint-container tip"><p class="hint-container-title">Non-Destructive Drafting</p><p>Applying generated fields writes content only to the active browser form controls. It <strong>never</strong> auto-saves or publishes the product without your consent. You can make manual tweaks and click <strong>Publish</strong> or <strong>Update</strong> when ready.</p></div><hr><h2 id="_2-inline-wysiwyg-editor-ai-targeted-text-generation-refinement" tabindex="-1"><a class="header-anchor" href="#_2-inline-wysiwyg-editor-ai-targeted-text-generation-refinement"><span>2. Inline WYSIWYG Editor AI (Targeted Text Generation &amp; Refinement)</span></a></h2><p>For moments when you only want to write or refine specific sections of copy without opening the full product assistant, Magic AI places a dedicated button directly on the WordPress editor toolbar.</p><blockquote><p><strong>Editor Toolbar Buttons:</strong><br> Above the Short Description and Main Description WYSIWYG editors, administrators have two dedicated buttons: <strong>[ Magic AI ]</strong> for text composition/refinement and <strong>[ Generate Image ]</strong> for AI artwork generation.</p></blockquote><p><a class="doc-image-link" href="./assets/marketplace-admin-editor-magic-ai-toolbar.webp"><img src="'+n+'" alt="Magic AI Button on WordPress WYSIWYG Editor Toolbar"></a></p><h3 id="how-to-use-the-editor-assistant" tabindex="-1"><a class="header-anchor" href="#how-to-use-the-editor-assistant"><span>How to Use the Editor Assistant:</span></a></h3><ol><li>Click the <strong>Magic AI</strong> button located directly above the editor.</li><li>The <strong>AI Assistance</strong> popup appears: <ul><li><strong>Prompt Field:</strong> Enter instructions for what to write or how to rewrite existing copy.<br><em>Examples:</em><ul><li><em>&quot;Write 4 bullet points highlighting waterproof features and durability.&quot;</em></li><li><em>&quot;Make this description sound more premium and formal.&quot;</em></li><li><em>&quot;Summarize the specifications into a concise closing paragraph.&quot;</em></li></ul></li><li><strong>Select Model:</strong> Choose from available text models configured in your Providers tab.</li></ul></li><li>Click <strong>Generate</strong>.</li><li>Inspect the generated text preview. Click <strong>Apply</strong> to insert the text directly into the active editor at your cursor position.</li></ol><p><a class="doc-image-link" href="./assets/marketplace-admin-editor-magic-ai-modal.webp"><img src="'+s+'" alt="Inline Editor AI Assistance Popup with Prompt and Model Selector"></a></p><hr><h2 id="_3-ai-product-image-generation" tabindex="-1"><a class="header-anchor" href="#_3-ai-product-image-generation"><span>3. AI Product Image Generation</span></a></h2><p>Store managers can create high-resolution product imagery, promotional banners, or conceptual product visuals using AI.</p><h3 id="how-to-generate-product-images" tabindex="-1"><a class="header-anchor" href="#how-to-generate-product-images"><span>How to Generate Product Images:</span></a></h3><ol><li>Click the <strong>Generate Image</strong> button located on the editor toolbar.</li><li>The image generation dialog opens: <ul><li><strong>Prompt:</strong> Describe the desired scene, lighting, and product setting in detail (e.g., <em>&quot;Professional commercial studio shot of a stainless steel insulated water bottle on a wet slate rock, dramatic side lighting, high resolution&quot;</em>).</li><li><strong>Aspect Ratio:</strong> Choose between <strong>Square (1:1)</strong>, <strong>Portrait (2:3)</strong>, or <strong>Landscape (3:2)</strong>.</li><li><strong>Model:</strong> Select your configured image generation model (e.g., Gemini or OpenAI).</li></ul></li><li>Click <strong>Generate Image</strong>.</li><li>Review the generated image preview.</li><li>Click <strong>Set as Product Image</strong>. The artwork is automatically downloaded, added to your WordPress Media Library, and assigned as the WooCommerce Featured Image.</li></ol><hr><h2 id="_4-category-taxonomy-ai-integration" tabindex="-1"><a class="header-anchor" href="#_4-category-taxonomy-ai-integration"><span>4. Category &amp; Taxonomy AI Integration</span></a></h2><p>Administrators can maintain rich, search-engine-friendly category landing pages:</p><ul><li><strong>Category Descriptions:</strong> On the WooCommerce Category editing screens (<code>Products &gt; Categories</code>), use the <strong>Magic AI</strong> button on the category description editor to draft engaging collection summaries.</li><li><strong>Category Thumbnails:</strong> Use the <strong>Generate Image</strong> tool to create consistent, high-impact header artwork for category landing pages across your marketplace.</li></ul><p><a class="doc-image-link" href="./assets/marketplace-admin-category-magic-ai.webp"><img src="'+l+'" alt="Category Description Magic AI Integration"></a></p>',31)]))}]]),g=JSON.parse('{"path":"/documentation/magic-ai-admin-content-generation.html","title":"Magic AI Admin Content Generation","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"1. The Product Page AI Assistant (Multi-Field Generator)","slug":"_1-the-product-page-ai-assistant-multi-field-generator","link":"#_1-the-product-page-ai-assistant-multi-field-generator","children":[{"level":3,"title":"Where to Find It","slug":"where-to-find-it","link":"#where-to-find-it","children":[]},{"level":3,"title":"Step-by-Step Workflow","slug":"step-by-step-workflow","link":"#step-by-step-workflow","children":[]}]},{"level":2,"title":"2. Inline WYSIWYG Editor AI (Targeted Text Generation & Refinement)","slug":"_2-inline-wysiwyg-editor-ai-targeted-text-generation-refinement","link":"#_2-inline-wysiwyg-editor-ai-targeted-text-generation-refinement","children":[{"level":3,"title":"How to Use the Editor Assistant:","slug":"how-to-use-the-editor-assistant","link":"#how-to-use-the-editor-assistant","children":[]}]},{"level":2,"title":"3. AI Product Image Generation","slug":"_3-ai-product-image-generation","link":"#_3-ai-product-image-generation","children":[{"level":3,"title":"How to Generate Product Images:","slug":"how-to-generate-product-images","link":"#how-to-generate-product-images","children":[]}]},{"level":2,"title":"4. Category & Taxonomy AI Integration","slug":"_4-category-taxonomy-ai-integration","link":"#_4-category-taxonomy-ai-integration","children":[]}],"git":{},"filePathRelative":"documentation/magic-ai-admin-content-generation.md"}')}}]);